package com.prince.currencyexchange.service; import com.prince.currencyexchange.dto.*; import com.prince.currencyexchange.entity.CurrencyRate; import com.prince.currencyexchange.exception.*; import com.prince.currencyexchange.repository.*; import org.springframework.stereotype.Service; import java.math.*; import java.util.*; @Service public class CurrencyService { private final CurrencyRepository currencyRepository; private final CurrencyRateRepository currencyRateRepository; public CurrencyService(CurrencyRepository c,CurrencyRateRepository r){this.currencyRepository=c;this.currencyRateRepository=r;} public Map<String,CurrencyResponse> getAllCurrencies(){Map<String,CurrencyResponse> out=new LinkedHashMap<>(); currencyRepository.findAll().forEach(c->out.put(c.getCurrencyCode(),new CurrencyResponse(c.getCountryName(),c.getCurrencyCode(),c.getCurrencyName()))); return out;} public ExchangeRateResponse getExchangeRate(String fromCur,String toCur){String from=normalizeCurrencyCode(fromCur); String to=normalizeCurrencyCode(toCur); validateCurrencyExists(from); validateCurrencyExists(to); if(from.equals(to)) return new ExchangeRateResponse(from,to,new BigDecimal("1.0")); var direct=currencyRateRepository.findByCurrencyCodeFromAndCurrencyCodeTo(from,to); if(direct.isPresent()) return new ExchangeRateResponse(from,to,direct.get().getExchangeRate()); var rev=currencyRateRepository.findByCurrencyCodeFromAndCurrencyCodeTo(to,from); if(rev.isPresent()){BigDecimal inv=BigDecimal.ONE.divide(rev.get().getExchangeRate(),4,RoundingMode.HALF_UP); return new ExchangeRateResponse(from,to,inv);} throw new ExchangeRateNotFoundException("Exchange rate not found for "+from+" to "+to);} public String normalizeCurrencyCode(String c){if(c==null||c.isBlank()) throw new CurrencyNotFoundException("Currency code is required"); return c.trim().toUpperCase(Locale.ROOT);} public void validateCurrencyExists(String code){ if(!Set.of("INR","USD","CAD","EUR","AUD","AED").contains(code) || !currencyRepository.existsByCurrencyCode(code)) throw new CurrencyNotFoundException("Unsupported currency code: "+code);} }